enum Shape {
    Circle(f64),
    Rect { w: f64, h: f64 },
}

impl Shape {
    fn area(&self) -> f64 {
        match self {
            Shape::Circle(r) => r * r * 3.0,
            Shape::Rect { w, h } => w * h,
        }
    }
}

fn main() {
    println!("{}", Shape::Rect { w: 2.0, h: 5.0 }.area());
}

