enum Op {
    Add(i32, i32),
    Neg(i32),
    Nop,
}

fn run(o: Op) -> i32 {
    match o {
        Op::Add(a, b) => a + b,
        Op::Neg(x) => -x,
        Op::Nop => 0,
    }
}

fn main() {
    println!("{}", run(Op::Add(2, 3)) + run(Op::Neg(4)) + run(Op::Nop));
}
